INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_69_m_69_2_34',
  'Which of the following is a benefit of Infrastructure as Code (IaC) that helps in auditing and compliance?',
  'mcq',
  '["The infrastructure definition in code provides a clear, versioned audit trail of all changes.","IaC automatically generates compliance reports for all industry standards.","IaC eliminates the need for security audits by enforcing best practices.","IaC encrypts all configuration files, making them inaccessible to auditors."]'::json,
  '{0}',
  'Option A (correct) is a key benefit for auditing and compliance. Because infrastructure is defined in version-controlled code, every change, who made it, and when, is recorded. This provides an immutable audit trail, making it much easier to demonstrate compliance and track infrastructure evolution. Option B (incorrect) is false; IaC does not automatically generate compliance reports. Option C (incorrect) is an overstatement; while IaC helps enforce best practices, it does not eliminate the need for audits. Option D (incorrect) is false; while configurations can be secured, making them inaccessible to auditors would hinder, not help, compliance.',
  NOW(),
  'quiz_domain69_16',
  NOW(),
  19,
  NULL,
  NULL,
  'm_69_2',
  'medium'
);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_69_m_69_2_35',
