  'medium'
);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_70_m_70_1_11',
  'What is the primary function of the `terraform init` command in the context of providers?',
  'mcq',
  '["To validate the syntax of the HCL configuration files.","To download and install the required provider plugins.","To generate an execution plan for infrastructure changes.","To apply the infrastructure changes to the cloud provider."]'::json,
  '{1}',
  'Option B (correct) is the primary function of `terraform init` related to providers. This command initializes the working directory by downloading and installing the necessary provider plugins declared in the `required_providers` block. Option A is done by `terraform validate`. Option C is done by `terraform plan`. Option D is done by `terraform apply`.',
