);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_70_m_70_1_13',
  'What is the purpose of the ''required_providers'' block in a Terraform configuration?',
  'mcq',
  '["To define the specific resources that Terraform should manage.","To declare the providers Terraform needs and optionally specify their version constraints.","To configure the remote backend for state storage.","To specify output values that should be displayed after applying changes."]'::json,
  '{1}',
  'Option B (correct) accurately describes the purpose of the ''required_providers'' block. It is used to declare which providers are necessary for the configuration and allows you to specify version constraints for those providers, ensuring consistent behavior. Option A is incorrect; resources are defined in ''resource'' blocks. Option C is incorrect; the remote backend is configured in the ''terraform'' block using the ''backend'' argument. Option D is incorrect; output values are declared using ''output'' blocks.',
  NOW(),
  'quiz_domain70_16',
