);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_70_m_70_1_14',
  'Which command is used to download and install provider plugins based on the ''required_providers'' block?',
  'mcq',
  '["terraform get","terraform init","terraform install","terraform update"]'::json,
  '{1}',
  'Option B (correct) is ''terraform init''. This command initializes a working directory, which includes downloading and installing the necessary provider plugins specified in the ''required_providers'' block. Option A, ''terraform get'', is used for modules, not providers. Option C, ''terraform install'', is not a standard Terraform command for providers. Option D, ''terraform update'', is not the primary command for initial provider download, though ''terraform init -upgrade'' can update providers.',
  NOW(),
  'quiz_domain70_16',
