INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_71_m_71_7_14',
  'A team is collaborating on a large Terraform project. To ensure consistent code style and avoid merge conflicts related to formatting, they have integrated `terraform fmt` into their pre-commit hooks. They want to verify that all `.tf` files in the current directory and its subdirectories are correctly formatted without modifying them, and exit with a non-zero status code if any files are not compliant. Which command should be used?',
  'mcq',
  '["terraform validate -check-format","terraform fmt -check -recursive","terraform format --verify","terraform style --check"]'::json,
  '{1}',
