);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_72_m_72_3_15',
  'What is the primary purpose of an input `variable` in Terraform?',
  'mcq',
  '["To allow users to customize aspects of a Terraform configuration without modifying the source code directly.","To store computed values within a module for internal use and readability.","To expose information about resources managed by Terraform to the user or other configurations.","To define a sequence of commands to execute on a remote resource after it has been created."]'::json,
  '{0}',
  'Option A (correct) accurately describes the primary purpose of an input `variable`. Variables act as parameters for a Terraform configuration, enabling reusability and customization without altering the core `.tf` files. Option B describes `locals`. Option C describes `outputs`. Option D describes `provisioners`.',
