);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_69_m_69_1_76',
  'A development team is migrating from manual infrastructure provisioning to Infrastructure as Code using Terraform. They want to ensure their deployments are consistent and repeatable. Order the actions that contribute to achieving consistency and repeatability with IaC.',
  'ordering',
  '["Review and approve changes through a pull request process before deployment.","Define infrastructure in a single, parameterized Terraform configuration.","Execute `terraform apply` using the shared and version-controlled configuration.","Store the Terraform configuration in a version control system like Git."]'::json,
  '{1,3,0,2}',
  'To achieve consistency and repeatability, the process starts with a well-defined and managed configuration. Option B (Define infrastructure in a single, parameterized Terraform configuration) sets up the reusable blueprint. This blueprint must be managed, so Option D (Store the Terraform configuration in a version control system like Git) is the next logical step. Collaboration and quality control are essential, making Option A (Review and approve changes through a pull request process before deployment) crucial. Finally, the consistent deployment is achieved by Option C (Execute `terraform apply` using the shared and version-controlled configuration).',
  NOW(),
  'quiz_domain69_16',
  NOW(),
  11,
  NULL,
  NULL,
  'm_69_1',
