INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_69_m_69_2_90',
  'Infrastructure drift occurs when the actual state of resources deviates from the defined configuration. Order the steps a team would typically take to detect and correct drift using Terraform.',
