INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_69_m_69_2_107',
  'Order the following benefits of IaC that specifically enhance team collaboration on infrastructure projects.',
  'ordering',
  '["Centralized, version-controlled infrastructure definitions","Standardized development and deployment workflows","Facilitates peer review of infrastructure changes","Reduces conflicts from manual, ad-hoc changes"]'::json,
  '{0,3,1,2}',
  'IaC enhances team collaboration by providing centralized, version-controlled infrastructure definitions (Option A), making it easy for all team members to access and track changes. This reduces conflicts from manual, ad-hoc changes (Option D) that can occur when multiple people modify infrastructure directly. It also leads to standardized development and deployment workflows (Option B), ensuring everyone follows the same process. Finally, IaC facilitates peer review of infrastructure changes (Option C), promoting knowledge sharing and quality assurance.',
  NOW(),
  'quiz_domain69_16',
  NOW(),
