INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_69_m_69_3_81',
  'Order the following statements to describe how Terraform''s provider model supports integrating with custom internal APIs.',
  'ordering',
