INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_70_m_70_2_65',
  'Arrange the following high-level steps in the correct order that Terraform takes to interact with a provider plugin during initialization.',
  'ordering',
  '["Terraform loads the provider plugin","Terraform discovers required providers in configuration","Terraform downloads the necessary provider plugin","Terraform initializes the provider for use"]'::json,
  '{1,2,0,3}',
  'The correct order for Terraform to interact with a provider plugin during initialization is: Option B (Terraform discovers required providers in configuration), then Option C (Terraform downloads the necessary provider plugin), followed by Option A (Terraform loads the provider plugin), and finally Option D (Terraform initializes the provider for use). Terraform first reads the configuration to identify which providers are needed. It then downloads the corresponding plugins. Once downloaded, the plugin is loaded into memory, and then initialized to establish communication and prepare for resource management.',
  NOW(),
  'quiz_domain70_16',
  NOW(),
  1,
  NULL,
  NULL,
  'm_70_2',
  'easy'
);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
