INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_70_m_70_4_97',
  'Order the actions Terraform takes to manage a resource''s lifecycle, from initial creation to deletion.',
  'ordering',
  '["Terraform marks the resource for destruction in the plan.","Terraform creates the resource and records it in state.","Terraform updates the resource based on configuration changes.","Terraform removes the resource from the state file after destruction."]'::json,
  '{1,2,0,3}',
  'The resource lifecycle begins with Terraform creating the resource and recording its details in the state file (Option B). Over time, if the configuration changes, Terraform updates the resource to reflect those changes (Option C). When the resource is no longer needed, Terraform marks it for destruction in the execution plan (Option A). After the resource is successfully destroyed in the cloud, Terraform removes its entry from the state file (Option D).',
  NOW(),
  'quiz_domain70_16',
  NOW(),
  50,
