  78,
  NULL,
  NULL,
  'm_71_7',
  'medium'
);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_71_m_71_7_64',
  'Which options are available with the `terraform fmt` command to control its behavior? (Select TWO.)',
  'multiple',
  '["The `-auto-approve` flag to bypass confirmation.","The `-check` flag to only check if files are formatted correctly without writing changes.","The `-target` flag to limit operations to specific resources.","The `-diff` flag to show differences between the current and formatted versions without writing.","The `-reconfigure` flag to re-initialize the backend."]'::json,
  '{1,3}',
  'Option B (correct) is true because `terraform fmt -check` is used to verify if the files are already formatted correctly, returning a non-zero exit code if they are not, without modifying them. Option D (correct) is true as `terraform fmt -diff` shows a diff of what changes would be made by formatting, without actually writing those changes to the files. Option A is incorrect; `-auto-approve` is for `terraform apply` or `destroy`. Option C is incorrect; `-target` is for `terraform plan` or `apply`. Option E is incorrect; `-reconfigure` is for `terraform init`.',
  NOW(),
  'quiz_domain71_16',
  NOW(),
  79,
  NULL,
  NULL,
  'm_71_7',
  'medium'
);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
