);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_71_m_71_7_74',
  'A junior engineer accidentally introduced inconsistent indentation and spacing in several Terraform configuration files. Which commands can help rectify this issue and ensure the code adheres to standard formatting? (Select TWO.)',
  'multiple',
  '["`terraform validate` to identify formatting errors.","`terraform fmt` to automatically reformat the files.","`terraform plan` to highlight formatting discrepancies.","`terraform fmt -recursive` to apply formatting across subdirectories.","`terraform init` to reset the formatting to default."]'::json,
  '{1,3}',
  'Option B (correct) `terraform fmt` is the command specifically designed to automatically rewrite Terraform configuration files to a canonical format, fixing indentation and spacing. Option D (correct) `terraform fmt -recursive` is used to apply the formatting changes to all `.tf` files within the current directory and its subdirectories, which is often necessary in larger projects. Option A (incorrect) `terraform validate` checks for syntax and configuration errors, not formatting style. Option C (incorrect) `terraform plan` generates an execution plan for infrastructure changes, it does not deal with code formatting. Option E (incorrect) `terraform init` downloads providers and modules and sets up the backend; it has no function related to code formatting.',
  NOW(),
  'quiz_domain71_16',
