INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_71_m_71_1_60',
  'Which commands are part of the core Terraform workflow cycle for managing infrastructure? (Select TWO.)',
  'multiple',
  '["`terraform plan`","`terraform destroy`","`terraform workspace`","`terraform taint`","`terraform graph`"]'::json,
  '{0,1}',
  'Option A (correct) `terraform plan` is a critical step for previewing changes. Option B (correct) `terraform destroy` is used to tear down infrastructure, completing the lifecycle. Option C (`terraform workspace`) is for managing separate state files within a configuration, which is outside the core provisioning/deprovisioning cycle. Option D (`terraform taint`) is deprecated in favor of `-replace`. Option E (`terraform graph`) is for visualizing dependencies, not a core workflow step.',
  NOW(),
  'quiz_domain71_16',
