INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_71_m_71_1_76',
  'Which of the following commands are part of the standard Terraform workflow cycle? (Select THREE.)',
  'multiple',
  '["`terraform init`","`terraform plan`","`terraform apply`","`terraform refresh`","`terraform validate`"]'::json,
  '{0,1,2}',
  'Option A (correct), Option B (correct), and Option C (correct) represent the core steps of the standard Terraform workflow: initialize, plan, and apply. Option D (incorrect) `terraform refresh` is a subcommand that updates the state file to reflect real-world infrastructure but is typically integrated into `plan` and `apply` by default, not a standalone step in the primary cycle. Option E (incorrect) `terraform validate` checks configuration syntax and consistency but is usually run before `plan` and `apply` as a preliminary check, not a core step in the change propagation cycle.',
  NOW(),
  'quiz_domain71_16',
