INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_73_m_73_1_18',
  'A small development team wants to share a common set of Terraform configurations as a module without setting up a private registry or a dedicated Git server. Which module source option would be the most straightforward for them to use if they already use a cloud provider?',
  'mcq',
  '["HTTP/HTTPS URL pointing to a ZIP archive in cloud storage (e.g., Amazon S3).","Terraform Registry (public).","Local file paths on each developer''s machine.","Bitbucket Cloud repository with SSH access."]'::json,
