  'mcq',
  '["s3::https://s3-REGION.amazonaws.com/BUCKET-NAME/PATH/TO/MODULE.zip","github.com/OWNER/REPO/PATH/TO/MODULE?ref=v1.0.0","registry.terraform.io/namespace/name/provider","./modules/my-local-module"]'::json,
  '{0}',
