INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_71_m_71_5_97',
  'A team is deploying a new web application infrastructure using Terraform. They have successfully initialized their working directory and generated an execution plan. Order the following steps to apply these changes to provision the infrastructure.',
  'ordering',
  '["Confirm the application by typing ''yes'' at the prompt (if not using -auto-approve)","Execute `terraform plan -out=tfplan` to create a saved plan file","Run `terraform apply tfplan` to execute the saved plan","Review the output of the apply command for successful resource provisioning"]'::json,
  '{1,2,0,3}',
  'Option B (correct) `terraform plan -out=tfplan` is the initial step to create a saved plan file, ensuring that the exact changes reviewed are the ones applied. Then, Option C `terraform apply tfplan` is used to execute that specific saved plan. If interactive approval is enabled, the user must confirm the application by typing ''yes'' at the prompt (Option A). Finally, it is important to review the output of the apply command (Option D) to verify that all resources were provisioned successfully and without errors.',
  NOW(),
  'quiz_domain71_16',
  NOW(),
  6,
  NULL,
  NULL,
  'm_71_5',
  'medium'
);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_71_m_71_5_98',
  'A team is automating their Terraform deployments in a CI/CD pipeline. They need to apply changes without manual intervention. Order the steps for an automated `terraform apply` workflow.',
  'ordering',
  '["Run `terraform init` to prepare the working directory","Execute `terraform plan -out=tfplan` to generate a plan file","Run `terraform apply -auto-approve tfplan` to apply the changes without prompt","Commit the Terraform configuration changes to version control"]'::json,
  '{3,0,1,2}',
